 const confirmImpact = async () => {
 if (!impact) return;
 setBusy("confirm-impact"); setMessage("");
 try { await commitPayload(impact.targetStage, impact.payload, impact.preview.preview_id); }
 catch (error) { setMessage(`变更未提交：${error.message}`); }
 finally { setBusy(""); }
 };

 // F-C real wait state (conference §4): while the pipeline owns a frozen
 // input (e.g. triaging), the impact confirm is pre-emptively disabled with
 // a truthful wait explanation and two exits instead of a late 409.
 const [queuedImpact, setQueuedImpact] = useState(null);
 const [impactCancelArmed, setImpactCancelArmed] = useState(false);
 const pipelineStageLabel = PIPELINE_STAGE_LABELS[pipelineStage] || pipelineStage || "";
 const pipelinePercentValue = Number(pipelineStatus?.pipeline?.percent);
 const authoringWaitHint = authoringWriteBlocked
 ? `研究流水线正在${pipelineStageLabel}${Number.isFinite(pipelinePercentValue) ? `（进度 ${pipelinePercentValue}%）` : ""}。任务在后台继续，刷新或离开页面均安全。`
 : "";

 // Exit A: the user chose "submit after the pipeline finishes". When the
 // stage leaves the blocked set, refresh the impact preview against the
 // CURRENT journey revision and reopen the panel — never a silent write.
 useEffect(() => {
 if (!queuedImpact || authoringWriteBlocked || !journey) return undefined;
 let cancelled = false;
 (async () => {
 try {
 const preview = await fetchImpactPreviewFor(queuedImpact.targetStage, queuedImpact.payload);
 if (cancelled) return;
 setQueuedImpact(null);
 if (preview.requires_confirmation) {
 setImpact({ preview, targetStage: queuedImpact.targetStage, payload: queuedImpact.payload, waitedForPipeline: true });
 setMessage("流水线已结束：请重新核验下方变更影响后确认提交。");
 } else {
 await commitPayload(queuedImpact.targetStage, queuedImpact.payload);
 }
 } catch (error) {
 if (cancelled) return;
 setQueuedImpact(null);
 setMessage(`等待后自动提交未完成：${error.message}；请重新提交一次。`);
 }
 })();
 return () => { cancelled = true; };
 }, [queuedImpact, authoringWriteBlocked, projectId, journey, commitPayload]);

 // Exit B: cancel the running pipeline through the existing endpoint, then
 // the frozen-input guard lifts and the staged change can be committed.
 // 0924V1-R03: every non-confirmed outcome ABORTS the combined action —
 // zero confirm attempts on failure, stale context, or accepted-but-pending
 // cancellation. On confirmed_terminal the impact preview is RECOMPUTED
 // fresh before committing (the pre-cancel preview_id is never reused).
 const fetchImpactPreviewFor = async (targetStage, payload) =>
 fetch(`/api/projects/${projectId}/medical-writing/authoring-journey/impact-preview`, {
 method: "POST",
 headers: { "Content-Type": "application/json" },
 body: JSON.stringify({ expected_revision: journey.revision, stage: targetStage, [targetStage]: payload }),
 }).then(readJson);

 const cancelPipelineThenSubmit = async () => {
 const outcome = await cancelResearchPipeline();
 setImpactCancelArmed(false);
 if (!impact) return;
 if (outcome.kind === "stale_context" || outcome.kind === "failed") return;
 if (outcome.kind === "accepted_pending") {
 // Cancellation accepted but the pipeline is not terminal yet: queue
 // the change — the queued effect reopens and re-verifies on terminal.
 setQueuedImpact(impact);
 setMessage("取消请求已受理：等待流水线结束后将自动重新核验本次变更。");
 return;
 }
 setBusy("confirm-impact"); setMessage("");
 try {
 const preview = await fetchImpactPreviewFor(impact.targetStage, impact.payload);
 if (preview.requires_confirmation) {
 setImpact({ preview, targetStage: impact.targetStage, payload: impact.payload, waitedForPipeline: true });
 setMessage("流水线已取消：请重新核验下方变更影响后确认提交。");
 } else {
 await commitPayload(impact.targetStage, impact.payload);
 setImpact(null);
 }
 } catch (error) {
 setMessage(`变更未提交：${error.message}`);
 } finally { setBusy(""); }
 };

 const overrideCorpusGate = async () => {
 const requestProjectId = projectId;
 const sourceRevision = journey.revision;
 const missingLabels = Array.isArray((journey?.corpus_gate || {}).missing_requirements)
 ? [...((journey?.corpus_gate || {}).missing_requirements || [])]
 : [];
 const ack = [...new Set(acknowledged || [])].sort();
 const reasonText = (overrideReason || "").trim();
 if (!missingLabels.every((label) => ack.includes(label))) {
 setMessage("例外放行前请逐项确认全部未满足条件。");
 return;
 }
 const overridePayload = { reason: reasonText, acknowledged_missing_requirements: ack };
 setBusy("override"); setMessage("");
 try {
 const idempotencyKey = await stableAuthoringWriteKey(requestProjectId, "corpus-override", sourceRevision, overridePayload);
 let response;
 try {
 response = await fetch(`/api/projects/${requestProjectId}/medical-writing/authoring-journey/corpus-gate/override`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ expected_revision: sourceRevision, ...overridePayload, actor: "medical_manager", idempotency_key: idempotencyKey }) }).then(readJson);
 } catch (error) {
 if (!shouldReconcileWrite(error)) throw error;
 response = await reconcileJourneyWrite(requestProjectId, (current) => current.revision > sourceRevision && current.corpus_gate?.override?.active && current.corpus_gate.override.reason === overridePayload.reason && writePayloadMatches([...(current.corpus_gate.override.acknowledged_missing_requirements || [])].sort(), overridePayload.acknowledged_missing_requirements));
 if (!response) throw error;
 }
 if (activeProjectRef.current !== requestProjectId) return;
 setJourney(response); setMessage("已记录医学例外放行；语料状态仍保持“未就绪”，缺口不会被隐藏。");
 } catch (error) { setMessage(`例外放行未完成：${error.message}`); }
 finally { setBusy(""); }
 };

