    def test_reference_preparation_batch_is_scoped_to_finalized_authoring_documents(self):
        reference = self.writing_reference_source

        self.assertIn(
            'import { ReferencePreparationBatchPanel } from "./ReferencePreparationBatchPanel";',
            reference,
