  useEffect(() => {
    if (!batchId || !active || pollSuspended) return undefined;
    const timer = globalThis.setInterval(() => loadBatch(batchId, { polling: true }), 2500);
    return () => globalThis.clearInterval(timer);
  }, [active, batchId, loadBatch, pollSuspended]);

