const revisionFollowupPlaceholders = {
 medical_writing_revision: "具体指出需要保留的事实和需要调整的表达，例如：保留全部数值与终点名称，合并重复句并将研究目的提前。",
 regulatory_tone: "具体指出义务强度或监管措辞问题，例如：保留原限制条件，将建议性表述改为可执行条款，但不得扩大禁止范围。",
