 );
}

function visibleTableTitle(block, fallback = "未命名表格") {
 return String(
 block?.structured_table?.title
 || block?.table_caption?.text
 || block?.title
 || block?.title_hint
 || fallback,
 ).trim();
}

function sourceTableCaptionText(block) {
