 >
 <Icon size={15} />
 </button>
 ))}
 <span className="rich-toolbar-separator" aria-hidden="true" />
 <label className="rich-color-control" title="文字颜色">
 <Palette size={15} aria-hidden="true" />
 <span
 className="rich-color-swatch"
