 >
 {segment.operation === "delete" ? "−" : segment.operation === "insert" ? "+" : ""}{segment.text}
 </mark>
 ))}
 </div>
 {suggestion.diff_source_hash && <small>差异绑定选区版本：{suggestion.diff_source_hash.slice(0, 12)}…</small>}
