 </li>
 ))}
 </ul>
 </div>
 )}
 {suggestion.protected_token_status && suggestion.protected_token_status !== "legacy_unavailable" && (
 <div className={`revision-protected-token-panel ${suggestion.protected_token_status}`} aria-label="受保护医学标识核验">
