  const hasNonDefaultSort = normalizedQuery.sortBy !== DEFAULT_RISK_CHECKLIST_QUERY.sortBy
    || normalizedQuery.sortDirection !== DEFAULT_RISK_CHECKLIST_QUERY.sortDirection;

